/** Devuelve un semáforo según el valor y un límite */
function SEMAFORO(valor, limite) {
  if (valor < limite) {
    return "🔴";              // por debajo del límite
  }
  if (valor < limite * 2) {
    return "🟡";              // cerca del límite
  }
  return "🟢";                // todo bien
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🎒 Mi hoja")
    .addItem("Poner fecha de hoy", "ponerFecha")
    .addToUi();
}

function ponerFecha() {
  SpreadsheetApp.getActiveRange().setValue(new Date());
}
